import uuid

import pytest

from bedrock_protocol import v1001, v2168, v2193, v2225

PACK_ID = uuid.UUID("01020304-0506-0708-090a-0b0c0d0e0f10")

# generated by gophertunnel 6353c49:
# &packet.DimensionData{Definitions: []protocol.DimensionDefinition{{Name: "test:dim",
#   Range: [2]int32{320, -64}, Generator: protocol.GeneratorOverworld, DimensionType: 1000}}}
V1001 = bytes.fromhex("0108746573743a64696d80057f02d00f")

# generated by gophertunnel b8bd735:
# &packet.DimensionData{Definitions: []protocol.DimensionDefinition{{Name: "test:dim",
#   Range: [2]int32{320, -64}, Generator: protocol.GeneratorOverworld, DimensionType: 1000,
#   PackID: uuid.MustParse("01020304-0506-0708-090a-0b0c0d0e0f10")}}}
V2168 = bytes.fromhex("0108746573743a64696d80057f02d00f0807060504030201100f0e0d0c0b0a09")

GOLDENS = [
    pytest.param(
        v1001.DimensionDataPacket(
            dimension_definitions={
                "test:dim": v1001.DimensionDefinitionGroup.DimensionDefinition(
                    height_maximum=320,
                    height_minimum=-64,
                    generator_type=v1001.GeneratorType.OVERWORLD,
                    dimension_type=1000,
                )
            }
        ),
        V1001,
        id="v1001",
    ),
    pytest.param(
        v2168.DimensionDataPacket(
            dimension_definitions={
                "test:dim": v2168.DimensionDefinitionGroup.DimensionDefinition(
                    height_maximum=320,
                    height_minimum=-64,
                    generator_type=v2168.GeneratorType.OVERWORLD,
                    dimension_type=1000,
                    pack_id=PACK_ID,
                )
            }
        ),
        V2168,
        id="v2168",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_dimension_data_is_packet_180(version):
    assert version.PACKETS[180] is version.DimensionDataPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_dimension_data_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_dimension_data_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_a_v1001_dimension_data_body_does_not_decode_as_a_v2168_one():
    with pytest.raises(ValueError, match="at byte"):
        v2168.DimensionDataPacket.from_bytes(V1001)


def test_a_v2168_dimension_data_body_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.DimensionDataPacket.from_bytes(V2168)


def test_dimension_data_2225_appends_the_cloud_height_and_its_flag():
    older = v2193.DimensionDataPacket(
        dimension_definitions={
            "test:dim": v2193.DimensionDefinitionGroup.DimensionDefinition(
                min_y=-64,
                height_range=384,
                generator_type=v2193.GeneratorType.OVERWORLD,
                dimension_type=1000,
                pack_id=PACK_ID,
                default_biome="plains",
            )
        }
    )
    newer = v2225.DimensionDataPacket(
        dimension_definitions={
            "test:dim": v2225.DimensionDefinitionGroup.DimensionDefinition(
                min_y=-64,
                height_range=384,
                generator_type=v2225.GeneratorType.OVERWORLD,
                dimension_type=1000,
                pack_id=PACK_ID,
                default_biome="plains",
                cloud_height=192,
                render_clouds=True,
            )
        }
    )
    assert bytes(newer)[: len(bytes(older))] == bytes(older)
    assert len(bytes(newer)) == len(bytes(older)) + 3


def test_dimension_data_2225_round_trips_the_cloud_height_and_its_flag():
    packet = v2225.DimensionDataPacket(
        dimension_definitions={
            "test:dim": v2225.DimensionDefinitionGroup.DimensionDefinition(cloud_height=192, render_clouds=True)
        }
    )
    assert v2225.DimensionDataPacket.from_bytes(bytes(packet)) == packet
